# 3 회차 고침 패치 (문서만) · 모든 바꿈은 정확한 글자 일치 · 기대 횟수가 아니면 아무것도 쓰지 않는다
# 쓰는 법: python3 -I fix/patch_r3.py check | apply
import sys, hashlib, pathlib

D = pathlib.Path(__file__).resolve().parent.parent
MEMO = D / 'memo_v3_2.md'
text = MEMO.read_text(encoding='utf-8')
orig = text
log = []


def rep(label, old, new, count=1):
    global text
    n = text.count(old)
    log.append((label, n, count))
    if n != count:
        return
    text = text.replace(old, new)


def between(label, start, end, new):
    """start 부터 end 끝까지 (둘 다 포함) 를 new 로 · start · end 는 한 번씩"""
    global text
    ns, ne = text.count(start), text.count(end)
    i = text.find(start); j = text.find(end, i + 1 if i >= 0 else 0)
    ok = ns == 1 and ne == 1 and i >= 0 and j > i
    log.append((label, (ns, ne, ok), (1, 1, True)))
    if not ok:
        return
    text = text[:i] + new + text[j + len(end):]


